<?php
require_once __DIR__ . '/../connect.php';
if(isset($_GET['status'])){ $id=(int)($_GET['id']??0); $status=trim($_GET['status']); $allowed=['Cho xac nhan','Da xac nhan','Da nhan phong','Hoan tat','Huy']; if($id>0 && in_array($status,$allowed,true)){ $s=$conn->prepare('UPDATE datphong SET trangthai=? WHERE id=?'); $s->bind_param('si',$status,$id); $s->execute(); }}
$sql="SELECT d.*,t.hoten,t.sdt,p.sophong,lp.tenphong FROM datphong d JOIN taikhoan t ON t.id=d.id_taikhoan JOIN phong p ON p.id=d.id_phong JOIN loaiphong lp ON lp.id=p.id_loaiphong ORDER BY d.id DESC";
$result=$conn->query($sql);
?>
<div class="page-wrap"><div class="section-title"><h1>Quản lý đặt phòng</h1><p>Kiểm tra và cập nhật trạng thái đặt phòng.</p></div><div class="admin-table-wrap"><table class="admin-table"><tr><th>Mã</th><th>Khách hàng</th><th>Phòng</th><th>Nhận</th><th>Trả</th><th>Khách</th><th>Tổng tiền</th><th>Trạng thái</th><th>Thao tác</th></tr><?php while($r=$result->fetch_assoc()): ?><tr><td>#<?= $r['id'] ?></td><td><?= htmlspecialchars($r['hoten']) ?><br><?= htmlspecialchars($r['sdt']) ?></td><td><?= htmlspecialchars($r['sophong']) ?><br><?= htmlspecialchars($r['tenphong']) ?></td><td><?= htmlspecialchars($r['ngaynhan']) ?></td><td><?= htmlspecialchars($r['ngaytra']) ?></td><td><?= (int)$r['sokhach'] ?></td><td><?= number_format($r['tongtien'],0,',','.') ?> đ</td><td><?= htmlspecialchars($r['trangthai']) ?></td><td><div class="admin-actions"><a class="btn" href="admin.php?page=bookingManagement&id=<?= $r['id'] ?>&status=Da xac nhan">Xác nhận</a><a class="btn btn-secondary" href="admin.php?page=bookingManagement&id=<?= $r['id'] ?>&status=Hoan tat">Hoàn tất</a><a class="btn btn-danger" href="admin.php?page=bookingManagement&id=<?= $r['id'] ?>&status=Huy">Hủy</a></div></td></tr><?php endwhile; ?></table></div></div>
